// openSeriesStore opens a fresh temp store for series tests.
func openSeriesStore(t *testing.T) *Store {
	t.Helper()
	s, err := Open(context.Background(), filepath.Join(t.TempDir(), "series.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })
	return s
}

// wantSeriesID recomputes the id scheme independently in the test (the first
// 16 lowercase hex chars of sha256 over the relative-path bytes) so the store's
// minting is checked against the contract, not against itself.
func wantSeriesID(libraryID int64, relativePath string) string {
	sum := sha256.Sum256([]byte(relativePath))
	return fmt.Sprintf("ser_%d_%s", libraryID, hex.EncodeToString(sum[:])[:16])
}

// TestSeriesRoundtrip covers box 1.2: PutSeries/GetSeries/GetSeriesByPath/
// QuerySeries/ListSeriesIDs over the series table — the ser_ id scheme, the
// (library_id, relative_path) upsert preserving id/created_at, the optional
// status filter, and the wrapped-ErrNoRows miss paths. The document is opaque
// JSON end to end (the store never parses it).
func TestSeriesRoundtrip(t *testing.T) {
	s := openSeriesStore(t)
	ctx := context.Background()

	doc := json.RawMessage(`{"parsed":{"serial_record":true,"dir_name_raw":"Show.2022.S01","backing":"directory","series_relative_path":"Show.2022.S01"},"ffprobe":{}}`)

	t.Run("put_then_get_by_id_and_path", func(t *testing.T) {
		if err := s.PutSeries(ctx, Series{
			ModuleID: "serial", LibraryID: 7, RelativePath: "Show.2022.S01",
			Document: doc, SchemaVersion: 1, Status: "pending",
		}); err != nil {
			t.Fatalf("PutSeries: %v", err)
		}
		wantID := wantSeriesID(7, "Show.2022.S01")

		got, err := s.GetSeries(ctx, wantID)
		if err != nil {
			t.Fatalf("GetSeries(%q): %v", wantID, err)
		}
		if got.ID != wantID {
			t.Errorf("ID = %q, want %q (ser_<libraryID>_<sha16hex16(relative_path)>)", got.ID, wantID)
		}
		if got.LibraryID != 7 || got.RelativePath != "Show.2022.S01" || got.ModuleID != "serial" {
			t.Errorf("identity fields = %+v, want lib 7 / Show.2022.S01 / serial", got)
		}
		if got.Status != "pending" || got.SchemaVersion != 1 {
			t.Errorf("status/schema = %q/%d, want pending/1", got.Status, got.SchemaVersion)
		}
		if string(got.Document) != string(doc) {
			t.Errorf("document round-trip = %s, want %s", got.Document, doc)
		}
		if got.CreatedAt.IsZero() || got.UpdatedAt.IsZero() {
			t.Errorf("timestamps not set: created=%v updated=%v", got.CreatedAt, got.UpdatedAt)
		}

		byPath, err := s.GetSeriesByPath(ctx, 7, "Show.2022.S01")
		if err != nil {
			t.Fatalf("GetSeriesByPath: %v", err)
		}
		if byPath.ID != wantID {
			t.Errorf("GetSeriesByPath ID = %q, want %q (same identity)", byPath.ID, wantID)
		}
	})

	t.Run("upsert_preserves_id_and_created_at", func(t *testing.T) {
		prior, err := s.GetSeriesByPath(ctx, 7, "Show.2022.S01")
		if err != nil {
			t.Fatalf("prior GetSeriesByPath: %v", err)
		}
		// Advance updated_at deterministically past the first write.
		time.Sleep(2 * time.Millisecond)
		updatedDoc := json.RawMessage(`{"parsed":{"serial_record":true,"backing":"directory"},"ffprobe":{}}`)
		if err := s.PutSeries(ctx, Series{
			ModuleID: "serial", LibraryID: 7, RelativePath: "Show.2022.S01",
			Document: updatedDoc, SchemaVersion: 1, Status: "ready",
		}); err != nil {
			t.Fatalf("upsert PutSeries: %v", err)
		}
		got, err := s.GetSeriesByPath(ctx, 7, "Show.2022.S01")
		if err != nil {
			t.Fatalf("post-upsert GetSeriesByPath: %v", err)
		}
		if got.ID != prior.ID {
			t.Errorf("ID = %q, want %q (preserved on conflict)", got.ID, prior.ID)
		}
		if !got.CreatedAt.Equal(prior.CreatedAt) {
			t.Errorf("CreatedAt = %v, want %v (preserved on conflict)", got.CreatedAt, prior.CreatedAt)
		}
		if got.Status != "ready" {
			t.Errorf("Status = %q, want ready (mutable field refreshed)", got.Status)
		}
		if string(got.Document) != string(updatedDoc) {
			t.Errorf("Document = %s, want the refreshed document", got.Document)
		}
		if !got.UpdatedAt.After(prior.UpdatedAt) {
			t.Errorf("UpdatedAt = %v, want after %v", got.UpdatedAt, prior.UpdatedAt)
		}
	})

	t.Run("query_series_status_filter", func(t *testing.T) {
		for _, tc := range []struct {
			rel    string
			status string
		}{
			{"B.Show", "pending"},
			{"A.Show", "ready"},
		} {
			if err := s.PutSeries(ctx, Series{
				ModuleID: "serial", LibraryID: 9, RelativePath: tc.rel,
				Document:      json.RawMessage(`{"parsed":{},"ffprobe":{}}`),
				SchemaVersion: 1, Status: tc.status,
			}); err != nil {
				t.Fatalf("PutSeries %s: %v", tc.rel, err)
			}
		}
		all, err := s.QuerySeries(ctx, 9, "")
		if err != nil {
			t.Fatalf("QuerySeries all: %v", err)
		}
		if len(all) != 2 || all[0].RelativePath != "A.Show" || all[1].RelativePath != "B.Show" {
			t.Fatalf("QuerySeries all = %+v, want A.Show then B.Show (relative_path order)", all)
		}
		ready, err := s.QuerySeries(ctx, 9, "ready")
		if err != nil {
			t.Fatalf("QuerySeries ready: %v", err)
		}
		if len(ready) != 1 || ready[0].RelativePath != "A.Show" {
			t.Fatalf("QuerySeries ready = %+v, want only A.Show", ready)
		}
		none, err := s.QuerySeries(ctx, 9, "deleted")
		if err != nil || len(none) != 0 {
			t.Fatalf("QuerySeries deleted = %+v (err=%v), want empty", none, err)
		}
	})

	t.Run("list_series_ids", func(t *testing.T) {
		ids, err := s.ListSeriesIDs(ctx, 9)
		if err != nil {
			t.Fatalf("ListSeriesIDs: %v", err)
		}
		want := []string{wantSeriesID(9, "A.Show"), wantSeriesID(9, "B.Show")}
		if len(ids) != 2 || ids[0] != want[0] || ids[1] != want[1] {
			t.Fatalf("ListSeriesIDs = %v, want %v", ids, want)
		}
		empty, err := s.ListSeriesIDs(ctx, 404)
		if err != nil {
			t.Fatalf("ListSeriesIDs empty: %v", err)
		}
		if empty == nil || len(empty) != 0 {
			t.Fatalf("ListSeriesIDs(empty library) = %v, want non-nil empty slice", empty)
		}
	})

	t.Run("misses_yield_wrapped_err_no_rows", func(t *testing.T) {
		if _, err := s.GetSeries(ctx, "ser_7_deadbeefdeadbeef"); !errors.Is(err, sql.ErrNoRows) {
			t.Errorf("GetSeries(unknown) = %v, want wrapped sql.ErrNoRows", err)
		}
		if _, err := s.GetSeriesByPath(ctx, 7, "Ghost.Show"); !errors.Is(err, sql.ErrNoRows) {
			t.Errorf("GetSeriesByPath(unknown) = %v, want wrapped sql.ErrNoRows", err)
		}
	})

	t.Run("deterministic_reopen", func(t *testing.T) {
		// A second PutSeries of an unchanged series (the re-scan path) lands on
		// the SAME row — series count stays 1 per identity.
		if err := s.PutSeries(ctx, Series{
			ModuleID: "serial", LibraryID: 7, RelativePath: "Show.2022.S01",
			Document:      json.RawMessage(`{"parsed":{},"ffprobe":{}}`),
			SchemaVersion: 1, Status: "ready",
		}); err != nil {
			t.Fatalf("re-scan PutSeries: %v", err)
		}
		all, err := s.QuerySeries(ctx, 7, "")
		if err != nil {
			t.Fatalf("QuerySeries: %v", err)
		}
		if len(all) != 1 {
			t.Fatalf("series rows = %d, want 1 (upsert, not insert)", len(all))
		}
	})
}

// TestSeriesEpisodesQuery covers the QueryItemsBySeries semantics (design.md
// §Interfaces §6): file-backed exact equality; directory-backed SQL prefix
// match + Go-side depth-1 filter — grandchildren and sibling subtrees excluded,
// no join column on items.
func TestSeriesEpisodesQuery(t *testing.T) {
	s := openSeriesStore(t)
	ctx := context.Background()

	putItem := func(rel string) {
		t.Helper()
		if err := s.PutItem(ctx, Item{
			ID: fmt.Sprintf("itm_3_%s", rel), ModuleID: "serial", LibraryID: 3,
			FileID: rel, RelativePath: rel, MediaType: "serial",
			Document:      json.RawMessage(`{"parsed":{},"ffprobe":{}}`),
			SchemaVersion: 1, Status: "pending",
		}); err != nil {
			t.Fatalf("PutItem %s: %v", rel, err)
		}
	}
	// Directory subtree: two direct episodes, one grandchild, one sibling dir.
	for _, rel := range []string{
		"Show/E01.mkv", "Show/E02.mkv",
		"Show/Extras/extra.mkv", // depth-2: NOT an episode of Show
		"Other/E09.mkv",         // sibling subtree: NOT an episode of Show
		"loose.mkv",             // root-level file (file-backed serial below)
	} {
		putItem(rel)
	}
	dirSeries := Series{ID: wantSeriesID(3, "Show"), ModuleID: "serial", LibraryID: 3, RelativePath: "Show"}
	fileSeries := Series{ID: wantSeriesID(3, "loose.mkv"), ModuleID: "serial", LibraryID: 3, RelativePath: "loose.mkv"}

	t.Run("directory_backed_depth1_only", func(t *testing.T) {
		items, err := s.QueryItemsBySeries(ctx, dirSeries, SeriesBackingDirectory)
		if err != nil {
			t.Fatalf("QueryItemsBySeries(directory): %v", err)
		}
		got := []string{items[0].RelativePath, items[1].RelativePath}
		want := []string{"Show/E01.mkv", "Show/E02.mkv"}
		if len(items) != 2 || got[0] != want[0] || got[1] != want[1] {
			t.Fatalf("episodes = %v, want %v (depth-1 only, relative_path order)", rels(items), want)
		}
	})

	t.Run("file_backed_exact_match", func(t *testing.T) {
		items, err := s.QueryItemsBySeries(ctx, fileSeries, SeriesBackingFile)
		if err != nil {
			t.Fatalf("QueryItemsBySeries(file): %v", err)
		}
		if len(items) != 1 || items[0].RelativePath != "loose.mkv" {
			t.Fatalf("episodes = %v, want exactly loose.mkv", rels(items))
		}
	})

	t.Run("wrong_backing_is_error", func(t *testing.T) {
		if _, err := s.QueryItemsBySeries(ctx, dirSeries, "vhs"); err == nil {
			t.Fatal("QueryItemsBySeries(unknown backing) = nil error, want error")
		}
	})

	t.Run("no_matches_yields_empty_slice", func(t *testing.T) {
		empty := Series{LibraryID: 3, RelativePath: "Ghost"}
		items, err := s.QueryItemsBySeries(ctx, empty, SeriesBackingDirectory)
		if err != nil {
			t.Fatalf("QueryItemsBySeries(no matches): %v", err)
		}
		if items == nil || len(items) != 0 {
			t.Fatalf("episodes = %v, want non-nil empty slice", items)
		}
	})
}

// rels projects items to their relative paths for failure messages.
func rels(items []Item) []string {
	out := make([]string, len(items))
	for i, it := range items {
		out[i] = it.RelativePath
	}
	return out
}

// TestTitleOverrides covers the title-override control table (serial-watch-flow
// D-1, box 1.1): the per-entity override persists (upsert, one row per entity,
// latest title wins), clears, clearing an absent override is a no-op, an
// unknown entity's set is refused with nothing written, and the underlying
// series and item documents stay byte-identical throughout — control state
// beside the document. Table-driven over the two id spaces sharing the one
// table (the ser_ prefix keeps them disjoint).
func TestTitleOverrides(t *testing.T) {
	ctx := context.Background()
	s := openSeriesStore(t)

	const seriesDoc = `{"parsed":{"serial_record":true,"dir_name_raw":"Show.2022.S01","backing":"directory"},"ffprobe":{}}`
	const itemDoc = `{"parsed":{"title":"Show.2022.S01E01"},"ffprobe":{}}`

	libID, err := s.CreateLibrary(ctx, "serial", "/media/titles", "Titles")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	if err := s.PutSeries(ctx, Series{
		ModuleID: "serial", LibraryID: libID, RelativePath: "Show.2022.S01",
		Document: json.RawMessage(seriesDoc), SchemaVersion: 1, Status: "ready",
	}); err != nil {
		t.Fatalf("PutSeries: %v", err)
	}
	sID := wantSeriesID(libID, "Show.2022.S01")
	iID := "itm_title_e01"
	if err := s.PutItem(ctx, Item{
		ID: iID, ModuleID: "serial", LibraryID: libID, FileID: "title-e01",
		RelativePath: "Show.2022.S01/E01.mkv", MediaType: "serial",
		Document: json.RawMessage(itemDoc), SchemaVersion: 1,
	}); err != nil {
		t.Fatalf("PutItem: %v", err)
	}

	// documentsUnchanged asserts both documents are byte-identical to their
	// seeds — the override write/clear never rewrites a document namespace.
	documentsUnchanged := func(t *testing.T) {
		t.Helper()
		sr, err := s.GetSeries(ctx, sID)
		if err != nil {
			t.Fatalf("GetSeries: %v", err)
		}
		if !bytes.Equal(sr.Document, []byte(seriesDoc)) {
			t.Fatalf("series document mutated:\n got:  %s\n want: %s", sr.Document, seriesDoc)
		}
		it, err := s.GetItem(ctx, iID)
		if err != nil {
			t.Fatalf("GetItem: %v", err)
		}
		if !bytes.Equal(it.Document, []byte(itemDoc)) {
			t.Fatalf("item document mutated:\n got:  %s\n want: %s", it.Document, itemDoc)
		}
	}

	cases := []struct {
		name     string
		entityID string
		titles   []string // set in order; the last write wins
	}{
		{"series_id", sID, []string{"Настоящий детектив", `Show "Authorized" — S01`}},
		{"item_id", iID, []string{"Эпизод 1 — Пилот"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			for _, title := range tc.titles {
				stored, err := s.SetTitleOverride(ctx, tc.entityID, title)
				if err != nil {
					t.Fatalf("SetTitleOverride %q: %v", title, err)
				}
				if stored.EntityID != tc.entityID || stored.Title != title || stored.UpdatedAt == "" {
					t.Fatalf("stored record = %+v, want entity %s / title %q / nonzero stamp", stored, tc.entityID, title)
				}
				got, err := s.GetTitleOverride(ctx, tc.entityID)
				if err != nil {
					t.Fatalf("GetTitleOverride: %v", err)
				}
				if got.Title != title || got.UpdatedAt != stored.UpdatedAt {
					t.Fatalf("lookup = %+v, want title %q byte-identical with stamp %q", got, title, stored.UpdatedAt)
				}
				documentsUnchanged(t)
			}

			// Exactly one control row per entity — the upsert, not append.
			var rows int
			if err := s.db.QueryRowContext(ctx,
				"SELECT COUNT(*) FROM title_overrides WHERE entity_id = ?", tc.entityID).Scan(&rows); err != nil {
				t.Fatalf("count rows: %v", err)
			}
			if rows != 1 {
				t.Fatalf("rows for %s = %d, want 1 (upsert, not append)", tc.entityID, rows)
			}

			// Clear, read absent, clear again — the second clear is a no-op.
			if err := s.ClearTitleOverride(ctx, tc.entityID); err != nil {
				t.Fatalf("ClearTitleOverride: %v", err)
			}
			if _, err := s.GetTitleOverride(ctx, tc.entityID); !errors.Is(err, sql.ErrNoRows) {
				t.Fatalf("GetTitleOverride after clear err = %v, want wrapped sql.ErrNoRows", err)
			}
			if err := s.ClearTitleOverride(ctx, tc.entityID); err != nil {
				t.Fatalf("ClearTitleOverride absent (must be a no-op): %v", err)
			}
			documentsUnchanged(t)
		})
	}

	t.Run("unknown_entity_refused", func(t *testing.T) {
		if _, err := s.SetTitleOverride(ctx, "itm_ghost", "Ghost"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("SetTitleOverride(unknown) err = %v, want wrapped sql.ErrNoRows", err)
		}
		// Nothing written: the unknown id still reads as absent.
		if _, err := s.GetTitleOverride(ctx, "itm_ghost"); !errors.Is(err, sql.ErrNoRows) {
			t.Fatalf("GetTitleOverride(unknown) err = %v, want wrapped sql.ErrNoRows", err)
		}
	})
}
